+  return (
+    <button
+      type="button"
+      role="switch"
+      aria-checked={session.featuredQuestions}
+      disabled={!session.featured}
+      onClick={() =>
+        update.mutate({ id: session.id, change: { featuredQuestions: !session.featuredQuestions } })
